import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

export const InventoryAccountabilityPanel: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [inventoryOwner, setInventoryOwner] = useState('');
  const [retentionYears, setRetentionYears] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getMSMEProfile();
      const profile = res?.data || {};
      const owner = profile?.operations?.ghgOperationalBoundary?.inventoryOwner;
      const years = profile?.manufacturingProfile?.evidenceRetentionYears;
      setInventoryOwner(typeof owner === 'string' ? owner : '');
      setRetentionYears(Number.isFinite(Number(years)) && years !== null && years !== '' ? String(years) : '');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to load inventory accountability');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const save = async () => {
    const trimmedYears = retentionYears.trim();
    if (trimmedYears) {
      const years = Number(trimmedYears);
      if (!Number.isInteger(years) || years < 1 || years > 50) {
        setError('Evidence retention must be a whole number of years from 1 to 50.');
        setSaved(false);
        return;
      }
    }
    setSaving(true);
    setError(null);
    setSaved(false);
    try {
      await ApiService.updateInventoryAccountability({
        inventoryOwner: inventoryOwner.trim(),
        evidenceRetentionYears: trimmedYears ? Number(trimmedYears) : null,
      });
      setSaved(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save inventory accountability');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Inventory accountability (ISO 14064)
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Name the person who prepares the inventory and the number of years the company keeps the evidence.
          Leave both blank until the company records them. A blank retention period stays open. Seven years is the minimum once a period is saved.
        </Typography>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}
        {saved && (
          <Alert severity="success" sx={{ mb: 2 }}>
            Inventory accountability saved.
          </Alert>
        )}

        <Stack spacing={2}>
          <TextField
            label="Inventory owner"
            fullWidth
            value={inventoryOwner}
            onChange={(e) => {
              setInventoryOwner(e.target.value);
              setSaved(false);
            }}
            placeholder="Name of the person responsible for the inventory"
          />
          <TextField
            label="Evidence retention (years)"
            fullWidth
            value={retentionYears}
            onChange={(e) => {
              setRetentionYears(e.target.value);
              setSaved(false);
            }}
            placeholder="Leave blank until the company decides"
            inputProps={{ inputMode: 'numeric', min: 1, max: 50 }}
          />
          <Button variant="contained" onClick={() => void save()} disabled={saving}>
            {saving ? 'Saving…' : 'Save inventory accountability'}
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default InventoryAccountabilityPanel;
