import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  MenuItem,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

type WasteLine = {
  route: string;
  tonnes: string;
  description: string;
};

const ROUTES = [
  { id: 'recycling', label: 'Recycled / recovered' },
  { id: 'landfill', label: 'Sent to landfill / dumpsite' },
  { id: 'incineration', label: 'Burned / incinerated' },
  { id: 'hazardous', label: 'Hazardous waste treatment' },
  { id: 'e_waste', label: 'E-waste handling' },
  { id: 'composting', label: 'Composted' },
];

const emptyLine = (): WasteLine => ({ route: 'recycling', tonnes: '', description: '' });

type Scope3Cat5WastePanelProps = {
  msmeFriendly?: boolean;
  title?: string;
  helperText?: string;
  hideExpertNotes?: boolean;
};

const Scope3Cat5WastePanel: React.FC<Scope3Cat5WastePanelProps> = ({
  msmeFriendly = false,
  title,
  helperText,
  hideExpertNotes = false,
}) => {
  const [lines, setLines] = useState<WasteLine[]>([emptyLine()]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<{
    totals?: { tonnes?: number; kgCo2e?: number };
    rows?: Array<{ routeLabel: string; tonnes: number; kgCo2e: number }>;
    disclaimer?: string;
  } | null>(null);

  const canSubmit = useMemo(
    () => lines.some((line) => Number(line.tonnes) > 0),
    [lines]
  );

  const run = async (persist: boolean) => {
    setLoading(true);
    setError(null);
    try {
      const payload = {
        persist,
        lines: lines
          .filter((line) => Number(line.tonnes) > 0)
          .map((line) => ({
            route: line.route,
            tonnes: Number(line.tonnes),
            description: line.description,
          })),
      };
      const res = await axios.post(
        buildApiUrl('/transactions/scope3-cat5-waste'),
        payload,
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );
      setResult(res.data?.data?.inventory || null);
    } catch (e) {
      setError(
        e instanceof Error
          ? e.message
          : msmeFriendly
            ? 'Could not save waste amounts. Check the numbers and try again.'
            : 'Cat 5 worksheet failed'
      );
    } finally {
      setLoading(false);
    }
  };

  const heading = title || (msmeFriendly
    ? 'Waste amounts by what happened to it'
    : 'Scope 3 Cat 5 — waste generated in operations');
  const help = helperText || (msmeFriendly
    ? 'Enter tonnes for each route. Use recycler slips or weighbridge notes if you have them.'
    : 'Enter tonnes by disposal route. Uses CPCB-context proxy factors for inventory prep.');

  return (
    <Box>
      {!hideExpertNotes && !msmeFriendly ? (
        <Alert severity="info" sx={{ mb: 1.5 }}>
          Recycling and e-waste amounts also help your waste take-back (EPR) proof under Compliance → Waste take-back.
        </Alert>
      ) : null}
      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
        {heading}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {help}
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
      <Stack spacing={1.5} sx={{ mb: 2 }}>
        {lines.map((line, index) => (
          <Stack key={index} direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <TextField
              select
              size="small"
              label={msmeFriendly ? 'What happened to this waste?' : 'Disposal route'}
              value={line.route}
              onChange={(e) => setLines((prev) => prev.map((row, i) => (
                i === index ? { ...row, route: e.target.value } : row
              )))}
              sx={{ minWidth: 220 }}
            >
              {ROUTES.map((route) => (
                <MenuItem key={route.id} value={route.id}>{route.label}</MenuItem>
              ))}
            </TextField>
            <TextField
              size="small"
              label="Tonnes"
              type="number"
              inputProps={{ min: 0, step: '0.01' }}
              value={line.tonnes}
              onChange={(e) => setLines((prev) => prev.map((row, i) => (
                i === index ? { ...row, tonnes: e.target.value } : row
              )))}
              sx={{ width: 120 }}
            />
            <TextField
              size="small"
              label={msmeFriendly ? 'Short note (optional)' : 'Note'}
              placeholder={msmeFriendly ? 'e.g. scrap metal to ABC Recycler' : undefined}
              value={line.description}
              onChange={(e) => setLines((prev) => prev.map((row, i) => (
                i === index ? { ...row, description: e.target.value } : row
              )))}
              sx={{ flex: 1 }}
            />
          </Stack>
        ))}
      </Stack>
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
        <Button size="small" onClick={() => setLines((prev) => [...prev, emptyLine()])}>
          {msmeFriendly ? 'Add another amount' : 'Add line'}
        </Button>
        <Button
          size="small"
          variant="outlined"
          disabled={!canSubmit || loading}
          onClick={() => { void run(false); }}
        >
          {msmeFriendly ? 'Preview total' : 'Calculate'}
        </Button>
        <Button
          size="small"
          variant="contained"
          disabled={!canSubmit || loading}
          onClick={() => { void run(true); }}
        >
          {msmeFriendly ? 'Save waste amounts' : 'Save to inventory'}
        </Button>
      </Stack>
      {result ? (
        <Box>
          <Typography variant="body2" sx={{ fontWeight: 700, mb: 1 }}>
            {msmeFriendly
              ? `Saved total: ${result.totals?.tonnes ?? 0} tonnes · about ${result.totals?.kgCo2e ?? 0} kg CO₂e`
              : `Total: ${result.totals?.kgCo2e ?? 0} kg CO₂e (${result.totals?.tonnes ?? 0} t)`}
          </Typography>
          <ScrollableTableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>{msmeFriendly ? 'What happened' : 'Route'}</TableCell>
                  <TableCell>Tonnes</TableCell>
                  <TableCell align="right">kg CO₂e</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {(result.rows || []).map((row, idx) => (
                  <TableRow key={`${row.routeLabel}-${idx}`}>
                    <TableCell>{row.routeLabel}</TableCell>
                    <TableCell>{row.tonnes}</TableCell>
                    <TableCell align="right">{row.kgCo2e}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </ScrollableTableContainer>
          {result.disclaimer && !msmeFriendly ? (
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
              {result.disclaimer}
            </Typography>
          ) : null}
          {msmeFriendly ? (
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
              These amounts also feed your carbon inventory. Exact emission factors can be refined later by your consultant.
            </Typography>
          ) : null}
        </Box>
      ) : null}
    </Box>
  );
};

export default Scope3Cat5WastePanel;
