import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import api from '../../services/api';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';

type Lever = {
  label?: string;
  annualCo2ReductionTonnes?: number;
  costPerTco2eInr?: number;
  creditEligibility?: { cctsEligible?: boolean; programme?: string };
};

export default function PatAbatementCurvePanel() {
  const [data, setData] = useState<{
    exampleNarrative?: string;
    sec?: { gapPercent?: number; meetsBenchmark?: boolean; actual?: number; patBenchmarkSec?: number };
    abatementCostCurve?: { levers?: Lever[] };
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await api.getPatAbatementCurve();
      if (res.success) setData(res.data);
      else setError(res.message || 'Failed to load PAT abatement curve');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load PAT abatement curve');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={2}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  const levers = data?.abatementCostCurve?.levers || [];

  return (
    <Card variant="outlined" sx={{ mt: 2 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          PAT abatement cost curve
        </Typography>
        {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
        {data?.exampleNarrative && (
          <Alert severity="info" sx={{ mb: 2 }}>
            {data.exampleNarrative}
          </Alert>
        )}
        {data?.sec && (
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            SEC gap: {data.sec.gapPercent ?? '—'}% vs PAT benchmark ({data.sec.actual ?? '—'} vs {data.sec.patBenchmarkSec ?? '—'})
          </Typography>
        )}
        <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Lever (ranked by ₹/tCO₂e)</TableCell>
                <TableCell align="right">tCO₂e/yr</TableCell>
                <TableCell align="right">₹/tCO₂e</TableCell>
                <TableCell>CCTS</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {levers.map((lever) => (
                <TableRow key={lever.label}>
                  <TableCell>{lever.label}</TableCell>
                  <TableCell align="right">{lever.annualCo2ReductionTonnes?.toLocaleString('en-IN')}</TableCell>
                  <TableCell align="right">{lever.costPerTco2eInr}</TableCell>
                  <TableCell>{lever.creditEligibility?.cctsEligible ? 'Eligible' : 'ESCert'}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </ScrollableTableContainer>
      </CardContent>
    </Card>
  );
}
